from robot.libraries.BuiltIn import BuiltIn


class EgateException(Exception):
    pass


class EgateInterface:
    def __init__(self):
        self.wts = self._get_current_ute_wtssim_lib_instance()

    def _send_egate_command(self, egate_command):
        return self.wts.execute_egate_command_and_wait_for_data(egate_command)

    @staticmethod
    def _get_current_ute_wtssim_lib_instance():
        return BuiltIn().get_library_instance('ute_wtssim')

    def send_command(self, egate_command):
        return self.wts.execute_egate_command(egate_command)

    def send_command_check_for_faults(self, egate_command):
        """
        Sends command and checks for faults.
        :param egate_command:   egate_command
        :return:                None
        """
        raw_throughput_string = self._send_egate_command(egate_command)
        self._check_for_egate_errors(raw_throughput_string)
        return raw_throughput_string

    def _check_for_egate_errors(self, raw_throughput_string):
        if 'Stats are supported only for Active UE' in raw_throughput_string:
            raise EgateException('Cannot get throughput data of UEs not in active mode')
        elif 'is not configured on eNB' in raw_throughput_string:
            raise EgateException('Cannot get throughput data of cell not configured on eNB')
        elif 'No ' in raw_throughput_string and ' MAC data for' in raw_throughput_string:
            raise EgateException(
                'Egate was not able to find valid throughput output:\n {}'.format(raw_throughput_string)
            )
